import React, { useState } from "react";

// Fake data gói premium
const plans = [
  { id: "starter", name: "Starter", price: 0, desc: "Dành cho người mới" },
  { id: "core", name: "Core", price: 3360000, desc: "Dành cho cá nhân" },
  { id: "grow", name: "Grow", price: 1800000, desc: "Dành cho doanh nghiệp" },
  { id: "max", name: "Max", price: 1440000, desc: "Gói cao cấp" },
];

// Fake durations
const durations = [
  { id: "1m", label: "1 tháng", factor: 1 },
  { id: "12m", label: "12 tháng", factor: 12 },
];

export default function Payments() {
  const [step, setStep] = useState(1);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [duration, setDuration] = useState("12m");
  const [paymentMethod, setPaymentMethod] = useState("vnpay");

  const handleNext = () => setStep((s) => s + 1);
  const handleBack = () => setStep((s) => s - 1);

  const total = selectedPlan
    ? plans.find((p) => p.id === selectedPlan).price *
      durations.find((d) => d.id === duration).factor
    : 0;

  return (
    <div className="w-full max-w-4xl mx-auto p-6">
      <div className="p-6 shadow-xl rounded-2xl border bg-white">
        {/* Step header */}
        <div className="mb-4 flex justify-between items-center">
          <h2 className="text-xl font-bold">
            {step === 1 && "Chọn gói Premium"}
            {step === 2 && "Chọn thời hạn"}
            {step === 3 && "Phương thức thanh toán"}
            {step === 4 && "Xác nhận thanh toán"}
            {step === 5 && "Hoàn tất"}
          </h2>
          <span className="text-sm text-gray-500">Bước {step}/5</span>
        </div>

        {/* Step content */}
        <div className="mt-4">
          {step === 1 && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {plans.map((plan) => (
                <div
                  key={plan.id}
                  className={`p-4 border rounded-xl cursor-pointer ${
                    selectedPlan === plan.id ? "border-blue-500 bg-blue-50" : ""
                  }`}
                  onClick={() => setSelectedPlan(plan.id)}
                >
                  <h3 className="font-semibold">{plan.name}</h3>
                  <p className="text-sm">{plan.desc}</p>
                  <p className="mt-2 font-bold">
                    {plan.price === 0
                      ? "Miễn phí"
                      : plan.price.toLocaleString("vi-VN") + "đ / năm"}
                  </p>
                </div>
              ))}
            </div>
          )}

          {step === 2 && (
            <div className="flex gap-4">
              {durations.map((d) => (
                <button
                  key={d.id}
                  className={`px-4 py-2 rounded border ${
                    duration === d.id
                      ? "bg-blue-500 text-white"
                      : "bg-white text-gray-700"
                  }`}
                  onClick={() => setDuration(d.id)}
                >
                  {d.label}
                </button>
              ))}
            </div>
          )}

          {step === 3 && (
            <div className="flex gap-4">
              <button
                className={`px-4 py-2 rounded border ${
                  paymentMethod === "vnpay"
                    ? "bg-blue-500 text-white"
                    : "bg-white text-gray-700"
                }`}
                onClick={() => setPaymentMethod("vnpay")}
              >
                VNPay
              </button>
              <button
                className={`px-4 py-2 rounded border ${
                  paymentMethod === "momo"
                    ? "bg-pink-500 text-white"
                    : "bg-white text-gray-700"
                }`}
                onClick={() => setPaymentMethod("momo")}
              >
                Momo
              </button>
            </div>
          )}

          {step === 4 && (
            <div className="p-4 border rounded-lg">
              <h3 className="font-semibold mb-2">Thông tin thanh toán</h3>
              <p>Gói: {selectedPlan}</p>
              <p>Thời hạn: {duration}</p>
              <p>Phương thức: {paymentMethod}</p>
              <p className="font-bold">
                Tổng: {total.toLocaleString("vi-VN")}đ
              </p>
            </div>
          )}

          {step === 5 && (
            <div className="p-4 border rounded-lg text-center">
              <h3 className="font-semibold text-green-600">
                🎉 Thanh toán thành công!
              </h3>
            </div>
          )}
        </div>

        {/* Step actions */}
        <div className="mt-6 flex justify-between">
          {step > 1 && step < 5 && (
            <button
              className="px-4 py-2 bg-gray-200 rounded-lg"
              onClick={handleBack}
            >
              Quay lại
            </button>
          )}
          {step < 5 && (
            <button
              className="px-4 py-2 bg-blue-500 text-white rounded-lg"
              onClick={handleNext}
              disabled={step === 1 && !selectedPlan}
            >
              Tiếp tục
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
